def get_cb_info_data(date):
    if date is None:
        date = time.strftime('%Y-%m-%d', time.localtime())
    elif date.replace('-', '')[:8].isdigit() is False or len(date) != 10:
        user_log.error('您输入的时间格式不正确，请使用正确的格式：YYYY-mm-dd')
        return pd.DataFrame(columns=cb_columns)
    cb_info_file = os.path.join(cb_info_path, 'cb_info.csv')
    try:
        df = pd.read_csv(cb_info_file, index_col=0)
    except BaseException:
        user_log.error('后台数据获取失败，错误信息：%s' % get_traceback_message())
        return pd.DataFrame(columns=cb_columns)
    curr_time = date
    df = df[df['maturity_date'] >= curr_time]
    df = df[df['list_date'] <= curr_time]
    df.drop(df[df.apply(lambda row: '--' in row.to_string(header=False), axis=1)].index, inplace=True)
    df.reset_index(inplace=True)
    df['bond_code'] = df.apply(lambda x: str(x['bond_code']) + x['stock_code'][-3:], axis=1)
    df['BondCode'] = df['bond_code']
    df.set_index('BondCode', inplace=True)
    df = df[['bond_code', 'bond_name', 'stock_code', 'stock_name', 'list_date', 'premium_rate', 'convert_date', 'maturity_date', 'convert_rate', 'convert_price', 'convert_value']]
    df[['premium_rate', 'convert_rate', 'convert_price', 'convert_value']] = df[['premium_rate', 'convert_rate', 'convert_price', 'convert_value']].astype('float')
    return df
def get_trend_data_common(query_date=None, stocks=None, market=None):
    if stocks is not None and market is not None:
        user_log.error('您的输入错误，请勿同时输入stocks和market')
        return {}
    get_trenddata = {}
    if query_date is None:
        date = datetime.datetime.now()
        query_date = date.strftime('%Y%m%d')
    elif len(query_date) != 8:
        user_log.error('您输入的时间格式不正确，请使用正确的格式：YYYYmmdd')
        return {}
    file_name = 'trenddata_%s.json' % query_date
    trenddata_path = os.path.join(trend_data_path, file_name)
    if query_date == datetime.datetime.now().strftime('%Y%m%d'):
        count = 0
        while not os.path.exists(trenddata_path):
            count += 1
            time.sleep(1)
            if count >= 2:
                time.sleep(1)
                break
            os.path.exists
    if not os.path.exists(trenddata_path):
        system_log.error('%s日文件不存在，请检查' % query_date)
        return {}
    with open(trenddata_path, 'r', 'utf-8') as fp:
        trenddata = json.load(fp)
        suffix = []
        for mark in market:
            suffix.append(mark.replace('XSHG', 'SS').replace('XSHE', 'SZ'))
        if len(trenddata) == 0:
            return get_trenddata
        else:
            for stock in trenddata:
                if stock.split('.')[1] in suffix:
                    pass
                continue
            return get_trenddata
    if type(market) == str:
        market = [market]
    if type(stocks) == str:
        stocks = stocks.replace('XSHG', 'SS').replace('XSHE', 'SZ')
        get_trenddata[stocks] = trenddata.get(stocks, None)
    elif type(stocks) == list:
        for stock in stocks:
            stock = stock.replace('XSHG', 'SS').replace('XSHE', 'SZ')
            get_trenddata[stock] = trenddata.get(stock, None)
    return get_trenddata
def get_reits_list_common(date=None):
    if date is None:
        date = time.strftime('%Y%m%d', time.localtime())
    else:
        data = check_datetime(date)
        if data['error_no'] != 0:
            system_log.error(data['error_info'])
            return []
        else:
            date = data['date']
            stocks_all = []
            if date >= time.strftime('%Y%m%d', time.localtime()):
                params = ['stock_pool', 'XSHG.CB.RET;XSHE.CB.RET;']
                result, flag = api_get_from_zeromq(str(params))
                if flag:
                    system_log.error('在线全部基础设施公募基金发生异常，默认返回空值')
                else:
                    stock_list = result['data']['stock_pool']
                    for i in stock_list:
                        i = i.replace('XSHE', 'SZ').replace('XSHG', 'SS')
                        stocks_all.append(i)
            elif os.path.exists(reits_list_status_path):
                stocks_df = pd.read_csv(reits_list_status_path, header=0, dtype=str, keep_default_na=False, index_col=False)
                now_df = stocks_df.query(f"List_date <= \'{date!s}\' & Delisting_date > \'{date!s}\'")
                stocks_all_list = list(now_df['stock_code'])
                stocks_all = [i.replace('XSHE', 'SZ').replace('XSHG', 'SS') for i in stocks_all_list]
            else:
                system_log.error('文件 %s不存在，请检查' % reits_list_status_path)
            return stocks_all
def get_fundamentals_common(security, table, fields=None, date=None, start_year=None, end_year=None, report_types=None, date_type=None, merge_type=None, end_date=None, count=None, is_dict=None, now=None, affi_cont_category=None, merged_flag=None, is_dataframe=False):
    if str(FINANCE_GET_MODE_SWITCH) == '1':
        return get_fundamentals_data(security, table, fields=fields, date=date, start_year=start_year, end_year=end_year, report_types=report_types, date_type=date_type, merge_type=merge_type, end_date=end_date, count=count, is_dict=is_dict, now=now, affi_cont_category=affi_cont_category, merged_flag=merged_flag, is_dataframe=is_dataframe)
    else:
        return get_fundamentals_local_data(security, table, fields=fields, date=date, start_year=start_year, end_year=end_year, report_types=report_types, end_date=end_date, count=count, is_dict=is_dict, now=now, is_dataframe=is_dataframe)
def check_limit_common(security, query_date_str=None):
    if type(security) == str:
        security = [security]
    check_stocks(security)
    query_today = 0
    if query_date_str is None:
        query_today = 1
    elif len(query_date_str) != 8:
        user_log.error('日期输入错误，请检查！')
        return {}
    else:
        data = check_datetime(query_date_str)
        if data['error_no'] != 0:
            user_log.error('日期输入错误，请检查！')
            system_log.error(data['error_info'])
            return []
        else:
            query_date_str = data['date']
            today_date_str = datetime.datetime.strftime(datetime.datetime.now(), '%Y%m%d')
            if today_date_str == query_date_str:
                query_today = 1
            elif query_date_str > today_date_str:
                user_log.error('输入日期大于当日，请检查！')
                return {}
            return_data = {}
            if query_today == 1:
                for symbol in security:
                    data = image_data.get(symbol)
                    try:
                        up_px = data.get('up_px', 0)
                        last_px = data.get('last_px', 0)
                        if up_px != 0 and last_px == up_px:
                            if data['offer_grp'][1][0] == 0:
                                return_data[symbol] = 1
                                continue
                            return_data[symbol] = 2
                            continue
                        else:
                            down_px = data.get('down_px', 0)
                            if down_px != 0:
                                if last_px == down_px:
                                    if data['bid_grp'][1][0] == 0:
                                        return_data[symbol] = -1
                                        continue
                                    return_data[symbol] = -2
                                    continue
                                else:
                                    return_data[symbol] = 0
                                    continue
                    except BaseException:
                        system_log.error('%s snapshot获取异常,涨跌停无法判断,默认返回为0' % symbol)
                        return_data[symbol] = 0
            else:
                data = get_price_common(security, query_date_str, query_date_str, '1d', ['close', 'high_limit', 'low_limit'], is_dict=True)
                for symbol in security:
                    try:
                        stock_data = data[symbol]
                        last_close = float(stock_data['close'])
                        if last_close == float(stock_data['high_limit']):
                            return_data[symbol] = 1
                            continue
                        elif last_close == float(stock_data['low_limit']):
                            return_data[symbol] = -1
                            continue
                        else:
                            return_data[symbol] = 0
                            continue
                    except BaseException:
                        return_data[symbol] = 0
            return return_data
def is_delisting_sorting_stock_real(stocks):
    params = "['delisting_marker', %s]" % stocks
    result, flag = api_get_from_zeromq(str(params))
    return_result = {}
    stock_list = []
    if not flag:
        stock_list = result['data']['delisting_marker_code']
    if not stock_list:
        for stock in stocks:
            return_result[stock] = False
    else:
        for stock in stocks:
            if stock not in stock_list:
                return_result[stock] = False
                continue
            return_result[stock] = True
    return return_result
def get_current_kline_count_common(str_time):
    hour = int(str_time[:2])
    minute = int(str_time[-2:])
    if hour == 9:
        if minute < 30:
            min_num = 0
        else:
            min_num = minute - 30
    elif hour == 10:
        min_num = minute + 30
    elif hour == 11:
        if minute > 30:
            min_num = 120
        else:
            min_num = minute + 90
    elif hour == 12:
        min_num = 120
    elif hour == 13:
        min_num = minute + 120
    elif hour == 14:
        min_num = minute + 180
    elif hour >= 15:
        min_num = 240
    elif hour < 9:
        min_num = 0
    else:
        min_num = 0
    return min_num
def get_dominant_contract_common(contract, date, now):
    if not date:
        date = get_qry_date(now, date=None, date_type='curr')
    elif isinstance(date, str):
        if not isVaildDate(date):
            raise ValueError('get_dominant_contract函数date参数入参格式有误,字符串类型仅支持传入YYYY-mmd-mm或YYYYmmdd格式')
        date = get_qry_date(now, date=date, date_type='curr')
        code = contract.split('.')[0]
        file_path = os.path.join(main_contract_month_info_path, code + '.pickle')
        with open(file_path, 'rb') as f:
            jsont = pickle.load(f)
        if date in jsont:
            return jsont[date]
        else:
            user_log.info(f'{contract!s}合约在{date!s}日期无主力合约数据')
            return dict()
    elif isinstance(date, datetime.date):
        date = get_qry_date(now, date=date, date_type='curr')
    else:
        raise ValueError('get_dominant_contract函数date参数入参格式有误')
def get_future_main_contract_month_common(contract, date):
    out_info = {}
    out_info[contract] = {}
    if contract == 'T888.CCFX':
        contract_tmp = 'T9888.CCFX'
    else:
        contract_tmp = contract
    url = f"{OPEN_API_URL!s}/{const.TABLE_URL['future_main_contract_month']!s}"
    params = {'trd_date': date, 'domi_prod_code': contract_tmp.split('.')[0]}
    error_msg, api_data = get_open_api_data(url, params, req_type='post')
    if error_msg['error_no'] != 0:
        return out_info
    elif api_data['data']:
        try:
            data = api_data['data'][0]
            out_info[contract]['corr_month_code'] = data['corr_prod_code']
            date = str(data['trd_date'])
            out_info[contract]['trade_date'] = date_str_type_change(date, '%Y%m%d', '%Y-%m-%d')
            out_info[contract]['month_contract_name'] = data['corr_prod_name']
        except BaseException:
            system_log.warning(f'{contract!s}合约解析GTN数据异常，返回内容：{api_data!s}')
    else:
        system_log.warning(f"{contract!s}合约获取GTN数据异常，详细信息：{api_data['error_info']!s}, 返回内容：{api_data!s}")
    return out_info
